<?php /* Template Name: Member Profile */ $user = sd_members_get_user(); get_header(); ?><main id="primary" class="sd-main sd-profile-main"><div class="sd-container sd-content-wrap"><?php if ( ! $user || ! sd_member_profile_allowed( $user->ID ) ) : ?><div class="sd-card sd-empty"><h1><?php esc_html_e( 'Profile unavailable', 'social-discovery' ); ?></h1><p><?php esc_html_e( 'This profile is private or no longer available.', 'social-discovery' ); ?></p></div><?php else : ?><div class="sd-profile-card"><?php get_template_part( 'template-parts/members/profile-header', null, array( 'user' => $user ) ); ?><div class="sd-profile-grid"><?php get_template_part( 'template-parts/members/profile-about', null, array( 'user' => $user ) ); get_template_part( 'template-parts/members/profile-interests', null, array( 'user' => $user ) ); get_template_part( 'template-parts/members/profile-activity', null, array( 'user' => $user ) ); ?></div></div><?php endif; ?></div></main><?php get_footer(); ?>
